const PackRow* packTable(std::size_t& count) {
    count = sizeof(kPacks) / sizeof(kPacks[0]);
    return kPacks;
}

const ValueRow* valueTable(std::size_t& count) {
    count = sizeof(kValues) / sizeof(kValues[0]);
    return kValues;
}

